P["LY-439"] = ("方向：本日晴、以晴為主而晨間帶陰。父母戌土、辰土兩現皆靜，雨象靜而不動；三爻兄弟申金動化妻財卯木，財爻化出發動，妻財動主晴（天時父財法）。本日先陰後晴、午後晴明。應期：本日之內（日檔），主座標即本日丁亥日，無外推。置信中。",
"卡面 tradition＝liuyao。已載面：主問本日陰晴；無錨點。天時用父母主雨、妻財主晴：父母兩現靜、妻財化出而動，動者勝靜，晴。動化方向：申金→卯木，金克木化出被克，財化出量級薄、只主晴而不主大晴持久，已調量級。對表無天時門類明寫。應期：日檔、本日即座標，三路不外列（本日已值，逢值即日），R61復推：初推逢值本日／復推化神卯木值日本日同指本日／同點。粒度核：陰晴斷項指針父靜財動兩項，保留。",
0.60, T(reason="三布爾皆false。"))
P["LY-440"] = ("方向：雪止轉晴在卯日。上爻妻財卯木發動主晴，子月木相、亥日水生財，財動有氣；化子孫子水回頭生財，晴象得生扶續力。父母未土世應兩現靜，雪象不動將退。應期雙層：窗口為三日之內，主座標取卯日（妻財逢值之日，單位：日）。置信中。",
"卡面 tradition＝liuyao。天時父財：財卯動生扶有氣主晴、父靜。動化方向：卯木→子水，水生木回頭生，吉向。反轉不齊。對表無天時門類明寫，按三步：日檔（連日雪問何日晴、近事）；D四路無沖起解法，實空不涉；三路逢值卯、填實卯、沖實申（沖？卯逢酉沖記酉）取逢值卯，舍酉沖財反傷。對決不觸發。R61復推：初推逢值卯日／復推填實卯日／同點。粒度核：陰晴指針財動＋回頭生兩項保留。",
0.65, T(reason="三布爾皆false。"))
P["LY-441"] = ("方向：本日陰有雨、以雨為主。父母申金居三爻，辰月土生金旺相，雨象有氣；妻財不上卦（本卦無財，伏於初爻兄弟子水下巳火），晴源伏藏不出。二爻子孫寅木世動化卯木化進只主雲氣流動不主晴。五爻官鬼戌土動化亥水，水氣化出助雨。應期：本日辰月己卯日（日檔），主座標即本日。置信中下。",
"卡面 tradition＝liuyao。天時：父申金旺相主雨、財巳火伏藏（伏神待出四項：伏得月生？巳火辰月休、飛子水克伏，待出不成立，晴面無據）。動化方向：子寅→卯化進、官戌→亥化出水氣。對表無天時明寫。應期日檔本日即點；R61復推初推父旺本日／復推化神亥水同指本日水氣／同點。粒度核：陰晴指針父旺＋財伏不出兩項保留二值。",
0.50, T(di=True, reason="財伏待出項數參半、晴雨一度存疑，disputed=true並降置信；主斷未翻轉，伏財非主用神留位故reserve=false。"))
P["LY-442"] = ("方向：雨止轉晴在寅日。上爻父母酉金發動本主雨續，然酉金午月休囚、卯日沖之為日破，雨勢被沖散；化子孫寅木，寅木為晴氣轉出之神。初爻子孫卯木應動化官鬼辰土，雲氣動而漸收。應期雙層：窗口為數日之內，主座標取寅日（化神子孫逢值之日，單位：日）。置信中下。",
"卡面 tradition＝liuyao。天時父財：父酉動而休囚逢日沖＝破（前置區分：休囚無根逢沖為破不作沖起），雨斷源；財午火三爻靜伏象弱。動化方向：父酉→子寅（金生水？寅木：酉金所化寅木為金克木化出被克，量級薄）、子卯→官辰化出泄。反轉不涉。破象過表：父破而無根無待出之路，雨勢按破加重散。應期日檔；D四路沖散雨神非解法路、記無沖起解法；三路逢值寅、填實酉、沖實卯（已沖）取化神逢值寅；對表無天時明寫；對決：寅與酉隔逾一步觸發——閘門無0、視野日檔同0、合流寅有父化＋子動兩路同指得1，寅勝。R61復推：初推逢值寅日／復推合流寅日／同點。粒度核：陰晴指針父破＋化神兩項保留。",
0.55, T(cm=True, reason="初看父母發動主雨續，經破象過表父休囚逢沖為破、雨源斷，主斷翻為轉晴，故changed_main=true。"))
P["LY-443"] = ("方向：久雪未即止，晴在申日。父母亥水居三爻，丑月水相、辰日土克而未盡，雪象尚有氣、近一二日仍陰雪；妻財未土、辰土雖現而靜，晴源不動。五爻官鬼酉金動化申金化退，待化神申金值日、金氣肅清之期雪止。應期雙層：窗口為一旬之內，主座標取申日（化神逢值之日，單位：日）。置信中下。",
"卡面 tradition＝liuyao。天時：父亥相主雪續、財靜。動化方向：官酉→申化退，退主雪勢漸退、非即晴。反轉不齊。應期日檔（久雪問晴近事）；三路逢值申、填實亥、沖實巳取化神逢值申（與雪退終局同向），舍亥父值反主雪；對表無天時明寫；對決：申亥隔逾一步觸發——閘門無0、視野同0、合流申有化退漸收一義記0（同機制不重計）、平手回原序：三步取一舍二已以終局同向取申，維持申。R61復推：初推逢值申日／復推化退填實申日／同點。粒度核：陰晴指針父相＋官化退兩項保留。",
0.50, T(reason="三布爾皆false。"))
P["LY-445"] = ("方向：有雨而量小、雨在卯日。三占合斷：初占父母卯木發動主雨，然未月木休、午日泄之，動化子孫辰土，雨源化土而弱，主小雨；二占離為火靜卦父母不現，雨象無續；三占官鬼寅木動化子孫酉金，與雨無涉。三占收斂為一場小雨、不成連雨。應期雙層：窗口為數日之內，主座標取卯日（父母逢值之日，單位：日）。置信中下（三占合斷）。",
"卡面 tradition＝liuyao。已載面：主問何日雨／雨量面；無錨點。天時以父母為雨：初占父卯動休泄化土弱、二占父不現、三占無父動，合斷小雨。動化方向：卯木→辰土化出泄、雨源減。對表無天時明寫。應期日檔；三路逢值卯、填實卯、沖實酉取逢值卯；對決不觸發。R61復推：初推逢值卯日／復推填實卯日／同點。粒度核：雨量『小』由父休泄＋化土兩指針支撐，保留等級帶表述。",
0.48, T(di=True, reason="三占合斷且二占盤面卡未附裝卦、據題面合斷，disputed=true降置信；未翻轉、無留位。"))
P["LY-446"] = ("方向：先晴後有雨、雨在酉日。三爻妻財午火應爻發動，財動本主晴旱，人或疑無雨；然財動化出父母酉金，化神正是雨神父母，財化父主晴極轉雨，酉金值日即雨至。應期雙層：窗口為一旬之內，主座標取酉日（化神父母逢值之日，單位：日）。置信中。",
"卡面 tradition＝liuyao。天時父財：財午動化父酉，化出方向核對：午火→酉金火克金化出被克，然所化六親為父母即雨源本身，類別以化出何親定轉應（財化父）。動化定性：化出父母主雨轉。反轉不齊。應期日檔；D四路無；三路逢值酉、填實酉、沖實卯取逢值酉；對表無天時明寫；對決不觸發。R61復推：初推逢值酉日／復推填實酉日／同點。粒度核：陰晴轉斷指針財動＋化父兩項保留。",
0.60, T(cm=True, reason="初看財動主旱無雨，經化出父母核對翻為有雨，故changed_main=true。"))
P["LY-449"] = ("方向：晴遲，晴在戌日。四爻皆動：妻財卯木兩現發動本主晴，然卯木辰月休、化兄弟酉金回頭克財，晴源自傷；官鬼巳火兩動化子孫亥水，水氣化出助陰；父母未土持世靜而辰月旺，雨象居世有根。財動而化克、父旺靜守，晴須待戌日沖辰月？戌沖辰動父位、兼財墓？取戌日為開晴關口。應期雙層：窗口為一旬之內，主座標取戌日（單位：日）。置信中下。",
"卡面 tradition＝liuyao。天時：父未旺主雨、財卯動化回頭克（卯→酉金克木，方向已核）晴源傷、官化子亥助水。動化定性回頭克。反轉不齊。應期日檔；D四路：戌沖辰（月建父位）近解法意、列候選；三路沖實戌、填實未、逢值卯取沖實戌（與晴終局同向），舍卯財值（財化克值反傷）；對表無天時明寫；對決：戌卯隔逾一步——閘門無0、視野同0、合流戌無0卯無0平手，回原序以終局同向取戌維持。R61復推：初推沖實戌日／復推填實未日異點，裁決依終局同向＋沖月父位占優保留戌、未入reasoning舍棄。粒度核：陰晴指針三項保留。",
0.45, T(reason="三布爾皆false：主斷晴遲直定；應期異路裁決已留痕，不作trigger存疑（定義債口徑，reason如實記）。"))
P["LY-451"] = ("方向：此夢大凶，主婦人有隨去之厄、近防病亡之險。世爻兄弟亥水發動化官鬼辰土，世動入辰墓又化官鬼（夫鬼），正是隨鬼入墓之象；五爻官鬼戌土（故夫）發動化兄弟亥水，鬼動來引、與世相接。午月亥水囚、丁亥日雖臨值而月囚，世入墓化鬼無回頭生扶持。應期雙層：窗口為一月之內，主座標取辰日（世化墓逢值之日，單位：日），此期前後最須防厄。置信中下；此為占斷參考，現實中應即就醫留意安全。",
"卡面 tradition＝liuyao（題為占夢、卡給六爻盤，按六爻作斷，夢占法不另起盤）。已載面：主問婦人夢故夫隨去吉凶／應期面；無錨點。用神以世為婦人本人：亥水午月囚、臨日、動化辰土官鬼入墓。原神金靜、忌即化鬼。動化方向：亥水→辰土土克水回頭克且化墓；官戌→亥水土克水化出被克（鬼引世）。方向定性回頭克化墓。反轉條件：化墓且無生扶一路——世臨日值有扶，此路未全成立，不以反轉名義、按合流A化墓：世休囚入化墓、墓未破，權重高入凶斷候選；合決策序第7步：世囚＋日月無生扶（臨日只值不生）＋化墓無沖開，三類近齊，斷凶而量級留『防厄』不直斷必死。掃查源絕不涉。四路：本氣−／元忌仇−／動化−／世應不計；合參凶向。對象對齊＋復述：主語逐條為婦人本人，鬼為故夫只作引象不承受應驗，同一。應期：月窗日點（趨避近事日檔）；三路逢值辰、沖實戌、填實辰取逢值辰；對表趨避無應期成文（對表注趨避按無此門類）明寫；對決不觸發。R61復推：初推逢值辰日／復推填實辰日／同點。粒度核：無病位斷項。",
0.55, T(reason="三布爾皆false：凶斷由世化墓直定未經翻轉程序；無留位；取用世為本人題面自明。"))
P["LY-452"] = ("方向：避亂不往北，往北反凶；就土方（西南未方／本地堅守土位）避之得安。眾議北取子孫水為吉，然子孫子水初爻巳月囚、丙戌日土克之，福神休囚受日克，北水之象無力反主陷；世爻父母戌土臨日旺相，土位有根可恃。五爻兄弟申金動化父母未土，動象亦歸土。終局：避向土方平安、北行不利。應期：即日啟程（日檔），主座標即丙戌本日。置信中。",
"卡面 tradition＝liuyao。已載面：主問通鄉避亂何方／方位面北（題面已載眾議）——錨點面：北方水象直讀與轉應已列：取轉應（水神囚克、土神臨日），舍直讀，理由盤面旺衰。 用神子孫為福神：子水巳月囚、日戌克；世父戌臨日旺。動化方向：申金→未土土？金化土為回頭生（土生金），化父母主歸宅土位。反轉不齊。四路：本氣（福神）−／世（本人位）＋／動化＋回頭生／世應不計；合參以世臨日旺＋化歸土定土方安。掃查俱無。對象對齊：所問通鄉眾人避向，應驗落眾人行止，同一。應期日檔即日；R61復推：初推世臨日本日／復推化神未土同主土位本日定行／同點。粒度核：方位斷項指針世臨日＋子孫囚克＋化土三項同指土方，保留方位級（西南未方為未土方位、兩指針以上）。",
0.60, T(cm=True, reason="主斷翻轉題面眾議北吉為北凶土安，changed_main=true；錨點轉應取舍已在basis留痕。"))
