P["LY-454"] = ("方向：道考得佳等、名次在前列中上。父母申金持世發動化酉金化進，文書試卷之神進益；官鬼戌土上爻與丑土應爻靜，官雖不動而父動化進主榜上有名且等第向前。應期雙層：窗口為放榜旬內，主座標取酉日（化神父母逢值之日，單位：日）。置信中。",
"卡面 tradition＝liuyao。已載面：主問道考名次／應期面；無錨點。用神父母申金世：亥月休、丙戌日生，動化酉金進。官鬼為名次之位靜。動化方向：申→酉化進吉向定性，靜態世應不壓。反轉不齊。四路：本氣0／元忌仇0／動化＋／世應不計；合參父進定佳等。掃查化進待沖：化神酉不空破、缺待實項，不作翻轉、作同向佐證。對象對齊：所問求測者考試，用神父申，應驗同人。應期日檔（發案近事）；對表發案門：父動者逢值逢合之日，化神酉逢值正對位取酉日；三路逢值酉、填實酉、沖實卯取逢值；對決不觸發。R61復推：初推逢值酉日／復推填實酉日／同點。粒度核：等第『前列中上』由父化進一指針，降為等級帶表述不斷名次數。",
0.60, T(reason="三布爾皆false。"))
P["LY-455"] = ("方向：歲考得佳等（一等可望）。父母亥水持世，申月金生水相、巳日沖之，旺相有氣逢沖為沖起暗動，文氣被引動；五爻官鬼酉金申月旺相發動化妻財未土，官旺動主等第之位高；上爻妻財未土動化子孫巳火不礙父官主線。應期雙層：窗口為考案旬內，主座標取亥日（父母逢值之日，單位：日）。置信中。",
"卡面 tradition＝liuyao。用神父母亥水世：申月相、乙巳日沖——日沖靜爻裁決：有氣（月相）判暗動按動計。官酉旺動化財（官化財：金→土？酉金化未土為回頭生，土生金，官得回生）。動化方向：官酉→未回頭生吉向、財未→子巳化出泄。反轉不齊。四路：本氣＋／元忌仇0／動化＋／世應不計；合參佳等。掃查俱無。對象對齊同一人。應期日檔；對表發案：父旺而靜（暗動）逢值沖之日，亥逢值兼巳日已沖，取亥值日；三路逢值亥、沖實巳、填實亥取逢值亥，舍巳（已過之沖不作未來座標）；對決：亥巳隔逾一步——閘門無0、視野同0、合流亥無0巳無0、回原序取逢值亥。R61復推：初推逢值亥日／復推填實亥日／同點。粒度核：等第一等由父暗動＋官旺動兩指針保留等級帶。",
0.60, T(reason="三布爾皆false：暗動裁決為常規程序、非主斷翻轉，reason如實記暗動已在basis留痕。"))
P["LY-457"] = ("方向：往楚買豆不得利、不宜往。妻財亥水居應靜，午月囚、戊子日水幫而仍囚於月，財靜囚無動生之源；子孫酉金上爻靜而午月囚，福源不動不生財；世官鬼卯木午月休、子日刑之，行亦費力。財福俱靜囚，往買只有本錢往返之耗。應期：月檔內無得利之期可取，主座標取亥月（財逢值之月，單位：月）僅為財氣轉值之期、屆時亦只平平。置信中。",
"卡面 tradition＝liuyao。用神妻財亥水應靜：午月囚、日幫。原神子孫酉靜囚、忌兄弟丑靜。四路：本氣−／元忌仇0／動化0靜卦／世應計（往他方買賣世應分指：應財囚不生世，記−意已並量級）；合參路1−路2非＋定敗向（不得利）。掃查俱無。對象對齊：所問求測者往楚貿易，財應驗落其本利，同一。應期月檔（遠行貿易）；三路逢值亥月、沖實巳月、填實亥月取逢值亥月作轉值座標並明言非得利期；對表求財無靜財囚之對位、往何方門對表無此門類明寫；對決不觸發。R61復推：初推逢值亥月／復推填實亥月／同點。粒度核：無具體斷項。",
0.58, T(reason="三布爾皆false。"))
P["LY-458"] = ("方向：母近不來、來期遠，待寅月才有來望。用神父母寅木居上爻，酉月金克木絕、戊申日又沖克之，父母臨絕逢沖無氣為破，母之行象已絕於近段；四爻妻財酉金應動化子孫戌土，動者非用神，只主家中耗費等待。行人門用神安靜絕破主未思歸、歸期尚遠。應期雙層：窗口為數月之內，主座標取寅月（父母出絕逢值之月，單位：月）。置信中。",
"卡面 tradition＝liuyao。已載面：主問母來否何時（題面明示問來否非平安）／關係面母；無錨點。用神父母寅木：酉月絕、申日沖克，無氣判日破（前置區分），不作沖起。候補唯一現卦父母。動爻財酉→子戌與用神無生克主線。四路：本氣−／元忌仇−（金鬼旺？官卯世靜、克父之金臨日月）／動化0（用神不動）／世應不計；合參敗向＝近不來。掃查：伏神不涉、沖起前置已判破不作翻轉。對象對齊＋行人復述：主語逐條為母本人，歸否應驗落母，同一。應期：行人對表遠應月（母在外遠行），尺度月檔；三路逢值寅月、沖實申月、填實寅月取逢值寅月；對表行人首選按用神狀態：絕破無對位點、次選無，記對表未取中按三步；對決不觸發。R61復推：初推逢值寅月／復推填實寅月／同點。粒度核：無具體斷項。",
0.60, T(ru=True, reason="父母絕破不定近歸、保留寅月出絕逢值應驗位，故reserve_used=true；主斷近不來未翻轉。"))
P["LY-501"] = ("方向：文書可領而遲，領在午日。用神父母不上卦，伏於初爻官鬼卯木之下？——賁屬艮宮，首卦艮為山初爻兄弟辰土，伏神父母午火伏於初爻兄弟辰土之下。伏神午火卯月旺相有氣，飛神辰土臨壬辰日值而旺，飛旺壓伏為待出之局：伏神待出四項得生扶臨值（月旺）一項、飛神空破墓絕不成立、無動爻生伏（靜卦）、日辰臨飛非沖飛，待出未定偏待出——文書須待沖飛之期。應期雙層：窗口為一旬之內，主座標取戌日（沖飛神辰土之日，單位：日）；午日（伏神逢值）為備選，只入reasoning不並陳。置信中下。",
"卡面 tradition＝liuyao。用神父母伏藏：先走飛伏清單——伏午火卯月旺（有用：伏旺相）、飛辰土臨日旺壓（無用面：飛旺）。伏神待出成文判別四項：1伏得月旺成立、2飛空破墓絕不成立、3動爻生伏無（靜卦）、4沖飛之路未現，滿足1項且根基第2項缺，按判別為待出未定偏弱；合流B兩條件只具伏有力一項，斷半出待應、不直斷必領於某日而取午值為主座標並降置信。原神不涉。對象對齊：所問求測者候文書，用神伏父午，應驗落文書至本人，同一。應期日檔；D四路沖起日（沖飛辰為戌日）有列候選、實空不涉；三路沖實戌、填實午、逢值午，取逢值午（伏逢值出伏之路與待出同向），舍戌沖飛（沖飛同時沖散伏位土火？戌沖辰只開飛、亦列備選入reasoning）；門類對表無候文書門明寫；對決：午戌隔逾一步——閘門項午不釋飛壓扣、戌釋飛壓得，閘門項戌勝——按對決裁決應取戌日。裁決：主座標取戌日（沖飛之日），午日降為備選只入reasoning，prediction_text已按裁決寫戌日單點。R61復推：初推逢值午日／復推沖飛戌日異點，經對決戌占優、保留戌日單點。粒度核：無具體斷項。",
0.52, T(ru=True, di=True, reason="伏神待出未定且應期對決翻點（午→戌），disputed=true；伏神應驗位保留故reserve_used=true；終局方向（遲領）未變故changed_main=false。另自報：prediction_text主座標仍寫午日、與basis對決裁決戌日不一致，為本席留痕瑕疵。"))
P["LY-502"] = ("方向：自陳可達、陳而無大害，吉向。四爻子孫午火發動，卯月旺相，子孫旺動克制官鬼申金、酉金，忌神官鬼受福神制，主申辯得解、上不深究；父母亥水（二爻，奏章）卯月休、辛巳日沖之，亥卯半合有根判暗動，文書被引動上達。應期雙層：窗口為一旬之內，主座標取亥日（父母逢值之日，單位：日）。置信中。",
"卡面 tradition＝liuyao。用神父母亥水：卯月休、日巳沖，有根（亥卯合）判暗動。官鬼兩現申酉：申卯月囚、酉囚，子孫午火旺動克之。動化方向：子午→財丑，火生土化出泄而仍主制官後耗。反轉不齊。四路：本氣0／元忌仇＋（子孫旺動制官）／動化0／世應不計；合參有救吉向。掃查俱無。對象對齊：所問求測者自陳，用神父亥，應驗同人。應期日檔；對表無自陳門明寫；三路逢值亥、沖實巳、填實亥取逢值亥；對決不觸發。R61復推：初推逢值亥日／復推填實亥日／同點。粒度核：無具體斷項。",
0.58, T(cm=True, reason="初看父母逢日沖似文書受阻，經暗動裁決有根判暗動、子孫制官，主斷定吉向有翻轉成分，故changed_main=true。"))
P["LY-503"] = ("方向：久病凶、不治之勢。世爻妻財寅木發動化官鬼巳火，世動化鬼又化泄，久病逢世化鬼最忌；官鬼午火三爻巳月旺相靜壓，病勢旺；子孫亥水（藥神）居應，巳月囚且亥巳沖為月破，藥神破而無力。近段纏綿沉重，遠段世化鬼、藥破無續，終局單判不治。應期雙層：窗口為一月之內（月檔），主座標取午日（官鬼逢值之日，單位：日）為危重關口。置信中；卡面日干支不全（僅記未日），旬空無從核，置信已降。",
"卡面 tradition＝liuyao；輸入殘損：asked_at僅『巳月未日』日干缺失，旬空與日辰生克無從全核，basis如實注明並降置信。用神自占以世寅木為本人、官午為病、子亥為藥。世寅巳月休、化巳火（化鬼化泄）。藥神亥月破。動化方向：寅木→巳火木生火化泄化鬼；定性凶向。反轉條件：非源絕路。原神（生世之水即藥神）月破：病占原神判別——藥神破而無動生扶，源絕三征近齊（休囚破、無生扶、鬼旺克世），然終局翻轉門檻不涉（初判即凶）。四路：本氣−／元忌仇−／動化−／世應不計；合參凶向；決策序第7步：世囚＋藥破無救＋化鬼，三類齊，許斷不治。掃查俱無同向佐證記。對象對齊＋病占復述：主語逐條為求測者本人，同一。病位不落（缺日干、依據鏈不全，明寫不妄斷）。應期：k定月檔（久病終局類不落日斷生死，座標午日僅作危重關口非死期）；對表疾病：世化鬼無對位、藥破取實破？藥破主藥無效不作愈期，記對表未取愈期點；三路逢值午、沖實子、填實午取逢值午為關口座標。R61復推：初推逢值午日／復推填實午日／同點。粒度核：死期不斷、只記關口，粒度已收束。",
0.55, T(reason="三布爾皆false；輸入殘損（日干缺失）已在basis注明並降置信，屬異常說明非trigger存疑。"))
P["LY-504"] = ("方向：目下功名不升。用神官鬼亥水居三爻應位發動，卯月休囚、戊戌日土克之，動化子孫辰土——辰土回頭克亥水且為水之墓，官動化回頭克入墓；上爻兄弟巳火世動化子孫戌土，世化子孫亦主剝官。官受克入墓、無原神生扶（妻財酉金靜而卯月囚），升遷落空。應期雙層：窗口為數月之內，主座標取亥日（官鬼逢值之日，單位：日）只見虛應消息、實升不至。置信中。",
"卡面 tradition＝liuyao。用神官鬼候選：現卦亥水動一現（初爻子水為變？初爻父母卯木——官只亥水一現，候選唯一）。亥水卯月休、日克、化辰土回頭克入墓。動化方向：亥水→辰土土克水回頭克無解（辰未受沖）；世巳→戌化出泄生官墓。方向定性回頭克。反轉條件：化墓且無生扶一路全成立——然其與初判同向（初判即不升），按掃查處置記同向佐證不作翻轉。四路：本氣−／元忌仇−／動化−／世應不計；合參敗向。掃查：源絕不涉、伏神不涉。對象對齊：所問將軍之侄功名，用神官亥，應驗落其本人，同一。應期月窗日點；對表功名發案為父用神門、本題問升遷官用神，對表無升遷門明寫；三路逢值亥、沖實巳、填實亥取逢值亥虛應。R61復推同點（逢值／填實亥）。粒度核：無具體斷項。",
0.65, T(reason="三布爾皆false：初判與終局同向、反轉條件同向佐證不計翻轉。"))
P["LY-505"] = ("方向：府尊可復職、復而遲。三占合斷：初占風山漸官鬼卯木臨應，卯月旺、子日生，官有氣；再占火地晉官鬼巳火兩現；三占雷風恆官鬼申金發動化酉金化進，官動化進主職位進復。三占官皆有氣、三占化進收束，復職可成。應期雙層：窗口為數月之內，主座標取酉日（化神官鬼逢值之日，單位：日）。置信中下（三占合斷）。",
"卡面 tradition＝liuyao。三占合斷口徑：成敗取三占收斂（官皆有氣＋三占官化進），細節以三占為近。用神官鬼：初卯旺、再巳、三申動化進。動化方向：申→酉化進吉向定性。反轉不齊。四路（三占）：本氣0／元忌仇0／動化＋／世應不計；合參成向。掃查化進待沖缺待實項、作同向佐證。對象對齊：所問府尊復職（代占），用神官，應驗落府尊本人，同一。應期月窗日點；三路逢值酉、填實酉、沖實卯取逢值酉；對表無復職門明寫；對決不觸發。R61復推：初推逢值酉日／復推填實酉日／同點。粒度核：無具體斷項。",
0.55, T(di=True, reason="三占合斷，disputed=true；三占同向未翻轉、無留位。"))
P["LY-506"] = ("方向：母病凶、多凶少吉。初占母病：用神父母巳火居二爻，未月火休土泄、丁亥日沖之，父母休囚無根逢沖判日破，母之元氣已破；上爻子孫酉金世動化官鬼寅木，藥神動而化鬼，藥反成病象；官鬼卯木應靜。父母破、藥化鬼，母病終局偏不治。再占子病一卦另列：子孫卯木初爻酉月絕、丁卯日沖克，子病亦見大險——兩占分開斷、不併作一終局。應期雙層：母病窗口為一月之內，主座標取巳日（父母逢值之日，單位：日）為危重關口。置信中。",
"卡面 tradition＝liuyao。已載面：主問母病＋再占子病（分開斷）。母病用神父母巳火：未月休、日亥沖，無根判日破（前置區分）。藥神子孫酉金動化官寅木（化鬼）。動化方向：酉金→寅木金克木化出被克、六親化官鬼主藥化病。反轉不齊。四路：本氣−／元忌仇−／動化−／世應不計；合參凶向；決策序第7步父母破無救近齊，斷凶力量級留關口不直斷死日。原神存續：生父之木官卯靜囚，源減近絕、未越掃查門檻作翻轉（初判即凶）。對象對齊＋病占復述：母病主語逐條為母、子病主語為子，分開寫明，同一各自。病位不落（依據鏈缺六神路，明寫不妄斷）。應期月檔關口巳日；疾病對表：用神日破無對位愈期、記對表未取愈期；三路逢值巳、沖實亥、填實巳取逢值巳關口。R61復推同點。粒度核：死期不斷。",
0.60, T(reason="三布爾皆false：兩占分開斷為對象對齊常規、非存疑；主斷直定未翻轉。"))
