P["LY-507"] = ("方向：終身財福平平、守成小康之下，無大富之命。妻財戌土持世靜，酉月休囚、未日刑之，財臨世而弱，主財來有限；妻財辰土又現，財兩現皆土弱。子孫（福神）不上卦，伏於四爻妻財戌土之下申金，酉月旺而伏藏不出，福分有而難發。財弱福伏，終身以守成為主。應期：年檔，主座標取逢生之年意象——以戌年（世財逢值之年，單位：年）為財氣較旺之年。置信中。",
"卡面 tradition＝liuyao。用神妻財兩現戌世、辰：皆酉月休囚，互比無空破，取持世戌為主、辰記落選（靜而非世）。福神子孫申金伏：飛財戌土生伏（飛生伏得長生面）、伏酉月旺，待出四項：伏旺得月氣1、飛空破不成立、無動生伏、無沖飛，待出未定，福不出。終身財福對表：世財不旺有氣？世休囚近無氣，對表逢生之年一路類取；三路年檔逢值戌年、沖實辰年、填實戌年取逢值戌年。對決不觸發。R61復推：初推逢值戌年／復推填實戌年／同點。粒度核：財福等級『小康之下』由財休囚＋福伏兩指針保留等級帶。四路：本氣−／元忌仇0／動化0／世應不計，合參平敗向（無大財）。",
0.58, T(ru=True, reason="伏福申金保留待出應驗位、財辰落選留記，故reserve_used=true；主斷未翻轉、主用取世已寫明不存疑。"))
P["LY-508"] = ("方向：終身財福中平、後段可復起至小康，戒賭則守得住。妻財亥水五爻申月相、壬子日水幫，財有氣；子孫酉金臨應申月旺，福源旺而生財；世爻兄弟辰土發動化丑土化退，劫財之性動而漸退，早年賭耗之象已見（題面已載因賭致貧，與卦面世兄動相合），兄化退主耗習漸收。財福有源、世兄退，終局取中平復起。應期：年檔，主座標取亥年（妻財逢值之年，單位：年）為財復旺之年。置信中下。",
"卡面 tradition＝liuyao。事實優先序：題面已載因賭致貧，世兄動化退與之相合、不另虛構。用神財亥水相有氣、福子酉旺。動化方向：兄辰→丑化退；定性化退。反轉／E檔：世非用神，兄化退按劫力退減讀、利財面。化退終局權重不套用神本體。四路：本氣＋／元忌仇0（兄動而化退、劫力減）／動化0／世應不計；合參中平成向。終身財福對表：財旺世有氣取逢生之年類，逢值亥年同指。R61復推：初推逢值亥年／復推填實亥年／同點。粒度核：等級小康由財相＋福旺兩指針保留。",
0.52, T(reason="三布爾皆false。"))
P["LY-509"] = ("方向：終身可成家、財福中平，以子孫生財之路（技藝經營、貨殖營生）成家。妻財酉金居應，丑月相、辰日生之，財有氣在外，須經營求之；子孫辰土二爻丑月旺、日臨其位，福源旺而生財；初爻父母寅木動化兄弟巳火，父母動主早年根基文憑一面費力、化兄主成家過程有同輩耗分。世兄弟午火主本人好動耗財，量級壓至中平。應期：年檔，主座標取酉年（妻財逢值之年，單位：年）。置信中下。",
"卡面 tradition＝liuyao。用神財酉金應：丑月相日生。原神子孫辰旺臨日。忌兄弟午世靜、寅父動化兄。動化方向：寅木→巳火木生火化出泄、化兄弟。反轉不齊。四路：本氣＋／元忌仇0／動化0／世應計（財居應生世？金不生火、財克？火克金世克應財主求之得，記＋意並量級）；合參中平成向。對表終身財福：財旺取逢生之年類、逢值酉年同指。R61復推同點（逢值／填實酉年）。粒度核：成家路徑『技藝經營』由子孫旺生財一指針，降為傾向表述已寫『之路』不斷行業名目。",
0.55, T(reason="三布爾皆false。"))
P["LY-510"] = ("方向：除功名外可為者，以子孫技藝福祿進身、終轉公門差使一途最合。二爻子孫亥水發動化官鬼午火，子孫主技藝醫卜營生，動而化官主以技得職、由私業轉入公門；世爻父母丑土初爻臨癸丑日值，根基文書一面有恃。妻財不上卦，純以財起家無源，故不取經商大賈之路。應期：年檔，主座標取亥年（子孫逢值之年，單位：年）為進身轉機之年。置信中下。",
"卡面 tradition＝liuyao。用神以所問『何事可為』取動爻子孫為主象：亥水酉月相、丑日土克，動化午火官鬼（水克火化出被克？亥水化午火：水克火為化出被本爻克，記化官而受制、進身費力）。世父母丑臨日。四路類參：子相0、世＋。對表無此門類明寫。應期年檔逢值亥年；R61復推：初推逢值亥年／復推填實亥年／同點。粒度核：行業斷項指針子孫動化官一項，按R61-REV1-4降一檔為傾向表述（『最合』不斷定唯一行業）。",
0.50, T(reason="三布爾皆false：粒度降檔為常規核、非存疑。"))
P["LY-511"] = ("方向：終身財福中平偏吉、小康有餘。子孫亥水四爻子月旺相，福源當令；妻財卯木二爻子月相、未日半合，財得福生且逢合有聚；世爻父母未土上爻臨未日值，本人根基有恃。財福相生、世臨日，終身衣食豐足而非鉅富。應期：年檔，主座標取卯年（妻財逢值之年，單位：年）為財旺之年。置信中。",
"卡面 tradition＝liuyao。用神財卯木：子月相、日合。原神子孫亥旺。世父母未臨日。四路：本氣＋／元忌仇0（兄弟酉靜）／動化0靜卦／世應不計；合參成向中平偏吉。對表終身財福：財福旺取逢生之年類、逢值卯年同指。R61復推：初推逢值卯年／復推填實卯年／同點。粒度核：等級『小康有餘』由福旺＋財相合兩指針保留。",
0.57, T(reason="三布爾皆false。"))
P["LY-512"] = ("方向：終身無大功名，僅虛名小就。官鬼寅木二爻靜，戌月休囚、卯日幫扶有限，官靜休主功名之位不顯；父母不上卦，伏於二爻官鬼寅木之下巳火，戌月休、日卯生伏，伏而待出未定，科名文憑一面有根而難發；世爻子孫申金四爻主本人與功名相剋（子孫剝官）且靜守。官休父伏，終局取無大功名。應期：年檔，主座標取寅年（官鬼逢值之年，單位：年）僅為名分小動之年。置信中。",
"卡面 tradition＝liuyao。用神官鬼寅木靜休；父母巳火伏：待出四項伏得日生1、飛官寅不空破、無動生伏、日卯非沖飛，待出未定保留應驗位。子孫申世靜克官。四路：本氣−／元忌仇−（子臨世）／動化0／世應不計；合參敗向。對表終身功名無專條明寫、按三步逢值寅年。R61復推：初推逢值寅年／復推填實寅年／同點。粒度核：無具體斷項。",
0.55, T(ru=True, reason="伏父母保留寅／巳應驗位，故reserve_used=true；主斷未翻轉、取用不存疑。"))
P["LY-513"] = ("方向：終身無實職功名，援例只得虛銜。官鬼不上卦，伏於二爻子孫辰土之下亥水：亥水巳月囚、又逢巳亥沖為月破，伏而月破；飛神子孫辰土巳月旺、乙卯日木克飛？卯木克土飛受日克一面，然伏神本身囚破無氣，待出根基（伏有氣）不成立，官伏難出。父母亦不上卦（旅無父母），科名之源雙缺。本人已援例（題面已載）與卦面官伏破相合：名器已得其名、不得其實。應期：年檔內無出仕之年可取，主座標取亥年（官伏逢值之年，單位：年）僅作虛應。置信中。",
"卡面 tradition＝liuyao。用神官鬼亥水伏：飛伏清單——伏囚破（無用：休囚無氣、值月破）、飛子孫辰旺克伏（水受土克）；待出四項：伏生扶無、飛空破墓絕無（飛受日克記受制半項不作空破）、無動生伏、沖飛之路日卯克飛一項，根基兩項俱缺，待出不成立，斷伏難出。父母缺如一並記。四路：本氣−／元忌仇−／動化0／世應不計；合參敗向。掃查伏神引撥四項缺三，不翻轉（初判即敗）。對象對齊同一人。應期年檔逢值亥年虛應；對表無終身功名出仕門明寫。R61復推：初推逢值亥年／復推填實亥年／同點（皆虛應座標）。粒度核：無具體斷項。",
0.60, T(reason="三布爾皆false：伏難出由飛伏清單直定、非保留應驗位（伏無出路已明斷），故reserve=false。"))
P["LY-514"] = ("方向：防流兵避之得安、平安向。上爻子孫酉金（福神）發動化父母巳火，福神動主避害有路；四爻兄弟丑土動化子孫酉金，兄化福主同輩阻力轉為護持；世爻官鬼卯木（兵象）巳月休、辰日未動克之，鬼勢不旺。福動鬼衰，預先防避可保人口平安。應期雙層：窗口為數日之內，主座標取酉日（福神逢值之日，單位：日）為避定之期。置信中。",
"卡面 tradition＝liuyao。用神趨避以子孫福神＋世安危：子酉巳月囚（？酉金巳月合絆一面）日辰生扶，動化巳火回頭克福？巳火克酉金為回頭克——量級：福神化回頭克主避路有阻、須早避；兄丑→子酉化出福神同向。官鬼卯世休。動化方向：子酉→父巳回頭克、兄丑→子酉化出用神之親（兄化福）。反轉不齊。四路：本氣（世官休）0／元忌仇＋（兄化福）／動化0／世應不計；合參避之得安而費力。掃查俱無。對象對齊：所問求測者一家防避，應驗落其人口，同一。應期日檔；對表趨避無應期成文（對表注）明寫；三路逢值酉、沖實卯、填實酉取逢值酉。R61復推同點。粒度核：無具體斷項。",
0.58, T(reason="三布爾皆false。"))
P["LY-515"] = ("方向：夫婦將來可和好、和而遲。地天泰為六合之卦，世應雖不相生而卦體主和；妻財亥水五爻酉月休、辛巳日沖之，財（妻）逢沖主目下口角離心正動；應爻子孫酉金旬空， 對方一面心意落空未定。待財逢值、應出空之期，兩心各回，和好可成。應期雙層：窗口為數月之內，主座標取亥日（妻財逢值之日，單位：日）。置信中下。",
"卡面 tradition＝liuyao。已載面：主問夫婦和好／關係面配偶；無錨點。用神妻財兩現亥五爻、子初爻：亥酉月休日沖（有根？亥得酉金應生——應空生力待實，記輕標記）、子水酉月相靜；互比取亥（動勢逢沖、近身五爻）為主、子保留逢值應驗位。世兄辰、應子酉空：應空判假空待出（酉得月建臨值有根，假空三項：臨月值、得？靜而空待出空）。婚姻類別讀法：泰六合主合、合優先於絆讀。四路：本氣0／元忌仇0／動化0靜卦／世應計（應空生世待實，記0）；合參以六合卦體＋財應待實定遲和。掃查俱無。對象對齊：所問夫婦雙方，財應驗落妻、世落夫，分開寫明未併。應期月窗日點；婚姻對表：靜而空者終不成指用神靜空——本例應空而財逢沖動勢，不直套，記對表未取中按三步逢值亥；對決不觸發。R61復推：初推逢值亥日／復推填實亥日／同點。粒度核：無具體斷項。",
0.50, T(ru=True, reason="妻財子水落選保留逢值應驗位、應空待出，故reserve_used=true；主斷遲和未翻轉、主用取舍已寫明不存疑。"))
P["LY-516"] = ("方向：升遷得缺、得山東缺（東方之缺）。官鬼兩現：初爻官鬼巳火發動，臨己巳日值旺相，動化妻財寅木回頭生官（木生火），官旺臨日化回頭生主必得缺且得生扶之缺；四爻官鬼午火靜為另一缺之象，午火未月相亦有氣，兩缺皆非空，然動而臨日者勝——巳火化寅木，寅主東方，與山東（東）相合，真定屬北不合化神方位。應期雙層：窗口為一月之內，主座標取寅日（化神逢值之日，單位：日）。置信中下（何地之辨憑化神方位一項，降置信）。",
"卡面 tradition＝liuyao。用神官鬼兩現巳動、午靜：過否決標記互比——巳動而臨日旺、午靜，取巳為主用神，午保留為另一缺應驗位（題面兩缺並陳）。動化方向：巳火→寅木木生火回頭生，吉向定性。反轉不齊。四路：本氣＋／元忌仇0（子孫不上卦？歸妹有子？子孫伏？記忌不旺）／動化＋／世應不計；合參成向。掃查俱無。對象對齊：所問求測者升遷，用神官巳，應驗同人；午官為真定缺之象分開寫明。應期日檔偏月窗；對表無升遷何方門明寫；三路逢值寅、填實寅、沖實亥取逢值寅。R61復推：初推逢值寅日／復推填實寅日／同點。粒度核：處所斷項『山東』支撐指針僅化神寅木方位一項，按R61-REV1-4應降為方位級——prediction已寫山東缺並括注東方，屬由題面兩缺中選一（題面已載二選一面、非新造處所），保留二選一斷法並降置信至0.55記於此。",
0.55, T(ru=True, reason="官鬼午火落選保留為真定缺應驗位，故reserve_used=true；主用取舍已寫明、何地二選一為題面已載面，不作disputed。"))
