def main():
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()), set(P.keys()) - set(IDS))
    os.makedirs(OUT, exist_ok=True)
    total = 0
    counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for cid in IDS:
        text, basis, conf, trig = P[cid]
        for k in counts:
            counts[k] += 1 if trig[k] else 0
        rec = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
        total += os.path.getsize(path)
    # verify per-id readback
    for cid in IDS:
        path = os.path.join(OUT, cid + ".json")
        with open(path, encoding="utf-8") as f:
            r = json.load(f)
        assert r["case_id"] == cid and set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
        assert set(r["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    print("written", len(IDS), "total_bytes", total, "trigger_counts", counts)

if __name__ == "__main__":
    main()
